def db_setting(key, default=""):
    try:
        conn = backend.get_db()
        cur = conn.cursor()
        cur.execute("SELECT value FROM settings WHERE key = ?", (key,))
        row = cur.fetchone()
        conn.close()
        return row["value"] if row else default
    except Exception:
        return default


def set_db_setting(key, value):
    conn = backend.get_db()
    cur = conn.cursor()
    cur.execute("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", (key, value))
    conn.commit()
    conn.close()


def run_async(coro, timeout=90):
    return asyncio.run(asyncio.wait_for(coro, timeout=timeout))


def find_vps(container):
    for owner_id, items in backend.vps_data.items():
        for index, vps in enumerate(items):
            if vps.get("container_name") == container:
                return str(owner_id), index, vps
    return None, None, None


def session_token(handler):
    cookie = handler.headers.get("Cookie", "")
    for item in cookie.split(";"):
        item = item.strip()
        if item.startswith("session="):
            token = item.split("=", 1)[1]
            if token in SESSIONS:
                return token
    return None


def authenticated(handler):
    return handler.client_address[0] not in BANNED_IPS and session_token(handler) is not None


def esc(value):
    return html.escape(str(value), quote=True)


def icon(name):
    icons = {
        "grid": "⌘", "server": "◈", "users": "◉", "activity": "⌁",
        "settings": "⚙", "logout": "↗", "play": "▶", "stop": "■",
        "pause": "Ⅱ", "trash": "⌫", "search": "⌕", "sun": "☼",
        "moon": "☾", "menu": "☰", "arrow": "→", "check": "✓",
    }
    return icons.get(name, "•")


